import {
  FDOInterface,
  FDO_SDK,
  DOM,
  PluginMetadata,
  type RenderOnLoadOutput,
} from '@anikitenko/fdo-sdk';
import css from './styles.css';
import { render } from './render';
import { actions } from './actions';
import { INITIAL_VIEW_STATE } from './shared/types';
import type { ViewState, ResultState } from './shared/types';

class WebToolsWorkbenchPlugin extends FDO_SDK implements FDOInterface {
  private readonly _metadata: PluginMetadata = {
    name: 'Web Tools Workbench',
    version: '1.0.0',
    author: 'Plugin Author',
    description: 'Local dashboard of deterministic browser tools: text, JSON, URL, SEO, media, and social previews.',
    icon: 'applications',
  };

  private viewState: ViewState = { ...INITIAL_VIEW_STATE };

  private jsonResult = { state: 'idle' as ResultState, message: 'Ready', formatted: '' };
  private categoryResult = { state: 'idle' as ResultState, message: 'Ready' };

  get metadata(): PluginMetadata {
    return this._metadata;
  }

  init(): void {
    // Backend lifecycle: no handlers are required for this purely UI-driven plugin.
  }

  render(): string {
    const dom = new DOM();
    const shellClass = dom.createClassFromStyle(css.shell);
    const dashboardClass = dom.createClassFromStyle(css.dashboard);
    const cardClass = dom.createClassFromStyle(css.card);
    const libraryClass = dom.createClassFromStyle(css.library);
    const workspaceClass = dom.createClassFromStyle(css.workspace);
    const resultClass = dom.createClassFromStyle(css.result);
    const dockClass = dom.createClassFromStyle(css.dock);

    return render({
      state: this.viewState,
      jsonResult: this.jsonResult,
      categoryResult: this.categoryResult,
      shellClass,
      dashboardClass,
      cardClass,
      libraryClass,
      workspaceClass,
      resultClass,
      dockClass,
    });
  }

  renderOnLoad(): RenderOnLoadOutput {
    return actions;
  }
}

new WebToolsWorkbenchPlugin();

