import type { ViewState, ResultState } from './shared/types';
import { renderDashboard } from './features/dashboard/render';
import { renderJsonWorkspace } from './features/json-workspace/render';
import { renderCategoryWorkspace } from './features/category-workspace/render';
import { renderLibrary } from './features/library/render';
import { renderPersonalSpace } from './features/personal-space/render';
import type { ResultPayload } from './shared/types';

export interface JsonResult {
  readonly state: ResultState;
  readonly message: string;
  readonly formatted: string;
}

export interface CategoryResult {
  readonly state: ResultState;
  readonly message: string;
  readonly output?: string;
}

export interface RenderProps {
  readonly state: ViewState;
  readonly jsonResult: JsonResult;
  readonly categoryResult: CategoryResult;
  readonly shellClass: string;
  readonly dashboardClass: string;
  readonly cardClass: string;
  readonly libraryClass: string;
  readonly workspaceClass: string;
  readonly resultClass: string;
  readonly dockClass: string;
}

export const render = (props: RenderProps): string => {
  const { state, shellClass, dashboardClass, cardClass, libraryClass, workspaceClass, resultClass, dockClass } = props;

  let mainView = '';
  if (state.view === 'json') {
    mainView = renderJsonWorkspace({
      state,
      resultState: props.jsonResult.state,
      resultMessage: props.jsonResult.message,
      formatted: props.jsonResult.formatted,
    });
  } else if (state.view === 'category' && state.category) {
    mainView = renderCategoryWorkspace({
      category: state.category,
      resultState: props.categoryResult.state,
      resultMessage: props.categoryResult.message,
      resultOutput: props.categoryResult.output,
    });
  } else {
    mainView = renderDashboard({ state });
  }

  const libraryView = renderLibrary({ open: state.libraryOpen });
  const spaceView = renderPersonalSpace({ open: state.spaceOpen });

  return [
    `<div class="${shellClass}" data-role="tool-workbench" data-view="${state.view}">`,
    `  <main class="${dashboardClass} ${cardClass} ${workspaceClass} ${resultClass} ${dockClass}">`,
    mainView,
    `  </main>`,
    `  ${libraryView}`,
    `  ${spaceView}`,
    `</div>`,
  ].join('\n');
};

export default render;

