import type {
  ResultPayload,
  SocialInputs,
  ToolCategoryKey,
} from './types';

export interface TextCounts {
  readonly characters: number;
  readonly words: number;
}

export type TextTransform = 'upper' | 'lower' | 'title';

export function countText(text: string): TextCounts {
  const characters = [...text].length;
  const words = text.trim().length === 0 ? 0 : text.trim().split(/\s+/).length;
  return { characters, words };
}

export function titleCase(text: string): string {
  return text
    .split(/\s+/)
    .filter(Boolean)
    .map((word) =>
      word.charAt(0).toUpperCase() + word.slice(1).toLowerCase(),
    )
    .join(' ');
}

export function transformText(text: string, transform: TextTransform): string {
  if (transform === 'upper') return text.toUpperCase();
  if (transform === 'lower') return text.toLowerCase();
  return titleCase(text);
}

export function formatJson(input: string): ResultPayload {
  if (!input.trim()) {
    return { state: 'error', message: 'Paste a JSON value first.' };
  }
  try {
    const parsed: unknown = JSON.parse(input);
    const formatted = JSON.stringify(parsed, null, 2);
    return { state: 'success', message: 'Formatted with two-space indentation.', formatted };
  } catch (err) {
    const reason = err instanceof Error ? err.message : 'Invalid JSON';
    return { state: 'error', message: `Could not parse JSON: ${reason}` };
  }
}

export type DataOperation = 'json' | 'encode' | 'decode';

export function runDataOperation(
  input: string,
  operation: DataOperation,
): ResultPayload {
  if (operation === 'json') return formatJson(input);

  if (!input.trim()) {
    return { state: 'error', message: 'Paste text to process.' };
  }
  try {
    if (operation === 'encode') {
      const encoded = encodeURIComponent(input);
      return { state: 'success', message: 'URL-encoded the input.', formatted: encoded };
    }
    const decoded = decodeURIComponent(input);
    return { state: 'success', message: 'URL-decoded the input.', formatted: decoded };
  } catch (err) {
    const reason = err instanceof Error ? err.message : 'Invalid input';
    return { state: 'error', message: `Could not process URL query: ${reason}` };
  }
}

export interface SeoReport {
  readonly hasTitle: boolean;
  readonly title: string;
  readonly hasDescription: boolean;
  readonly description: string;
  readonly headingCounts: Record<'h1' | 'h2' | 'h3', number>;
  readonly linkCount: number;
  readonly imageCount: number;
  readonly imageAltCount: number;
  readonly imageAltCoverage: number;
}

interface ParsedTag {
  readonly name: string;
  readonly attributes: Record<string, string>;
}

const TAG_PATTERN = /<([a-zA-Z][a-zA-Z0-9:-]*)((?:[^>"']|"[^"]*"|'[^']*')*)>/g;

function parseTags(html: string): ParsedTag[] {
  const tags: ParsedTag[] = [];
  let match: RegExpExecArray | null = TAG_PATTERN.exec(html);
  while (match !== null) {
    const name = match[1].toLowerCase();
    const attributes: Record<string, string> = {};
    const attrPattern = /([a-zA-Z_:][a-zA-Z0-9_.:-]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g;
    let attr: RegExpExecArray | null = attrPattern.exec(match[2]);
    while (attr !== null) {
      const value = attr[2] ?? attr[3] ?? attr[4] ?? '';
      attributes[attr[1].toLowerCase()] = value;
      attr = attrPattern.exec(match[2]);
    }
    tags.push({ name, attributes });
    match = TAG_PATTERN.exec(html);
  }
  return tags;
}

function tagText(html: string, tagName: string): string {
  const open = new RegExp(`<${tagName}\\b[^>]*>([\\s\\S]*?)<\\/${tagName}>`, 'i');
  const match = open.exec(html);
  return match ? match[1].trim() : '';
}

export function analyzeHtml(html: string): ResultPayload {
  if (!html.trim()) {
    return { state: 'error', message: 'Paste HTML markup first.' };
  }
  const tags = parseTags(html);
  const title = tagText(html, 'title');
  const metaDescription =
    tags
      .find((tag) => tag.name === 'meta' && tag.attributes.name?.toLowerCase() === 'description')
      ?.attributes.content ?? '';
  const headingCounts = { h1: 0, h2: 0, h3: 0 };
  let linkCount = 0;
  let imageCount = 0;
  let imageAltCount = 0;
  for (const tag of tags) {
    if (tag.name === 'h1' || tag.name === 'h2' || tag.name === 'h3') {
      headingCounts[tag.name] += 1;
    } else if (tag.name === 'a') {
      linkCount += 1;
    } else if (tag.name === 'img') {
      imageCount += 1;
      const alt = tag.attributes.alt;
      if (typeof alt === 'string' && alt.trim().length > 0) imageAltCount += 1;
    }
  }
  const imageAltCoverage = imageCount === 0 ? 1 : imageAltCount / imageCount;
  const report: SeoReport = {
    hasTitle: title.length > 0,
    title,
    hasDescription: metaDescription.length > 0,
    description: metaDescription,
    headingCounts,
    linkCount,
    imageCount,
    imageAltCount,
    imageAltCoverage,
  };
  const coverage = Math.round(imageAltCoverage * 100);
  const lines = [
    `Title: ${title || 'missing'}`,
    `Description: ${metaDescription || 'missing'}`,
    `Headings: h1=${headingCounts.h1}, h2=${headingCounts.h2}, h3=${headingCounts.h3}`,
    `Links: ${linkCount}`,
    `Images: ${imageCount}, with alt text: ${imageAltCount} (${coverage}% coverage)`,
  ];
  return { state: 'success', message: 'SEO metrics computed locally.', formatted: lines.join('\n') };
}

export interface MediaReport {
  readonly type: string;
  readonly width?: number;
  readonly height?: number;
  readonly byteLength: number;
}

function detectDataUrlMime(input: string): string {
  const match = /^data:([a-z0-9.+-]+)?/i.exec(input);
  return match?.[1]?.toLowerCase() || 'unknown';
}

function base64ByteLength(data: string): number {
  const clean = data.replace(/[\r\n\s]/g, '');
  const pad = clean.endsWith('==') ? 2 : clean.endsWith('=') ? 1 : 0;
  return Math.max(0, Math.floor((clean.length * 3) / 4) - pad);
}

export function inspectMedia(input: string): ResultPayload {
  const value = input.trim();
  if (!value) {
    return { state: 'error', message: 'Paste a data URL or SVG markup first.' };
  }
  let type = 'svg';
  let width: number | undefined;
  let height: number | undefined;
  let byteLength = new Blob([value]).size;

  const dataUrl = /^data:[^,]+,(.*)$/s.exec(value);
  if (dataUrl) {
    type = detectDataUrlMime(value);
    if (type.includes('svg')) {
      const svg = decodeBase64OrText(dataUrl[1]);
      const dims = readSvgDimensions(svg);
      width = dims.width;
      height = dims.height;
    } else if (type.includes('base64')) {
      byteLength = base64ByteLength(dataUrl[1]);
    } else {
      byteLength = dataUrl[1].length;
    }
  } else if (/^\s*</.test(value)) {
    const dims = readSvgDimensions(value);
    width = dims.width;
    height = dims.height;
    type = /<svg[\s>]/i.test(value) ? 'svg' : 'markup';
  }

  const lines = [
    `Type: ${type}`,
    width !== undefined && height !== undefined ? `Dimensions: ${width}×${height}` : 'Dimensions: not reported',
    `Size: ${byteLength} bytes`,
  ];
  return { state: 'success', message: 'Media inspected locally.', formatted: lines.join('\n') };
}

function decodeBase64OrText(data: string): string {
  try {
    if (/^[a-z0-9+/=\s]+$/i.test(data) && data.length % 4 === 0) {
      const binary = atob(data.replace(/\s/g, ''));
      return binary;
    }
  } catch {
    // fall through to raw text
  }
  return data;
}

function readSvgDimensions(svg: string): { width?: number; height?: number } {
  const viewbox = /viewBox\s*=\s*["']?\s*([\d.]+)\s+([\d.]+)/i.exec(svg);
  if (viewbox) {
    return { width: Number(viewbox[1]), height: Number(viewbox[2]) };
  }
  const width = /width\s*=\s*["']?\s*([\d.]+)/i.exec(svg)?.[1];
  const height = /height\s*=\s*["']?\s*([\d.]+)/i.exec(svg)?.[1];
  return {
    width: width !== undefined ? Number(width) : undefined,
    height: height !== undefined ? Number(height) : undefined,
  };
}

export function parseSocialInputs(input: string): ResultPayload {
  const trimmed = input.trim();
  if (!trimmed) {
    return { state: 'error', message: 'Provide title, description, and URL fields.' };
  }
  const firstLine = trimmed.split('\n')[0].trim();
  if (firstLine.startsWith('{')) {
    try {
      const parsed: unknown = JSON.parse(firstLine);
      if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        return { state: 'error', message: 'Fallback JSON must be an object.' };
      }
      const record = parsed as Record<string, unknown>;
      const title = typeof record.title === 'string' ? record.title : '';
      const description = typeof record.description === 'string' ? record.description : '';
      const url = typeof record.url === 'string' ? record.url : '';
      return socialPreview({ title, description, url });
    } catch (err) {
      const reason = err instanceof Error ? err.message : 'Invalid JSON';
      return { state: 'error', message: `Could not parse fallback JSON: ${reason}` };
    }
  }
  return { state: 'error', message: 'Use the named fields or a fallback JSON object.' };
}

export function socialPreview(inputs: SocialInputs): ResultPayload {
  const { title, description, url } = inputs;
  const missing: string[] = [];
  if (!title.trim()) missing.push('title');
  if (!description.trim()) missing.push('description');
  if (!url.trim()) missing.push('url');
  if (missing.length > 0) {
    return { state: 'error', message: `Missing ${missing.join(', ')}.` };
  }
  let normalizedUrl = url.trim();
  if (!/^[a-z][a-z0-9+.-]*:/i.test(normalizedUrl)) {
    normalizedUrl = `https://${normalizedUrl}`;
  }
  let host = 'local preview';
  try {
    host = new URL(normalizedUrl).hostname;
  } catch {
    host = 'local preview';
  }
  const lines = [
    `Title: ${title.trim()}`,
    `Description: ${description.trim()}`,
    `URL: ${normalizedUrl}`,
    `Host: ${host}`,
    `Preview: local-only summary; URL was not fetched.`,
  ];
  return { state: 'success', message: 'Social preview generated locally.', formatted: lines.join('\n') };
}

export const CATEGORY_TOOL_LABEL: Record<ToolCategoryKey, string> = {
  text: 'Text & Content',
  data: 'Development & Data',
  seo: 'Web & SEO',
  images: 'Images & Media',
  social: 'Social & Platforms',
};

