import { defineRenderOnLoadActions } from '@anikitenko/fdo-sdk';
import {
  countText,
  titleCase,
  transformText,
  formatJson,
  runDataOperation,
  analyzeHtml,
  inspectMedia,
  parseSocialInputs,
  socialPreview,
} from './features/tools/logic';
import type { ResultPayload, SocialInputs, ToolCategoryKey } from './shared/types';
import { INITIAL_VIEW_STATE } from './shared/types';

const escapeHtml = (value: string): string =>
  value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function resultMessageHtml(payload: ResultPayload): string {
  const inner = payload.output
    ? `${escapeHtml(payload.message)}\n\n${payload.output}`
    : escapeHtml(payload.message);
  return inner.replace(/\n/g, '&#10;');
}

export const actions = defineRenderOnLoadActions({
  description: 'Web Tools Workbench navigation, library, personal space, JSON, and category tools.',
  handlers: {
    openLibrary: ({ document }) => {
      const library = document.querySelector('[data-role="tool-library"]');
      if (library) library.setAttribute('data-state', 'open');
      const workspace = document.querySelector('[data-role="tool-workbench"]');
      if (workspace) workspace.setAttribute('data-view', 'library');
    },
    closeLibrary: ({ document }) => {
      const library = document.querySelector('[data-role="tool-library"]');
      if (library) library.setAttribute('data-state', 'closed');
      const workspace = document.querySelector('[data-role="tool-workbench"]');
      if (workspace) workspace.setAttribute('data-view', 'dashboard');
    },
    openSpace: ({ document }) => {
      const sheet = document.querySelector('[data-role="tool-space-dialog"]');
      if (sheet) sheet.setAttribute('data-state', 'open');
      const workspace = document.querySelector('[data-role="tool-workbench"]');
      if (workspace) workspace.setAttribute('data-view', 'space');
    },
    closeSpace: ({ document }) => {
      const sheet = document.querySelector('[data-role="tool-space-dialog"]');
      if (sheet) sheet.setAttribute('data-state', 'closed');
      const workspace = document.querySelector('[data-role="tool-workbench"]');
      if (workspace) workspace.setAttribute('data-view', 'dashboard');
    },
    openJson: ({ document }) => {
      const dashboard = document.querySelector('[data-role="tool-dashboard"]');
      const json = document.querySelector('[data-role="tool-json-workspace"]');
      if (dashboard) dashboard.setAttribute('hidden', '');
      if (json) json.removeAttribute('hidden');
      const workspace = document.querySelector('[data-role="tool-workbench"]');
      if (workspace) workspace.setAttribute('data-view', 'json');
      const library = document.querySelector('[data-role="tool-library"]');
      if (library) library.setAttribute('data-state', 'closed');
      const sheet = document.querySelector('[data-role="tool-space-dialog"]');
      if (sheet) sheet.setAttribute('data-state', 'closed');
    },
    backDashboard: ({ document }) => {
      const dashboard = document.querySelector('[data-role="tool-dashboard"]');
      const json = document.querySelector('[data-role="tool-json-workspace"]');
      const category = document.querySelector('[data-role="tool-category-workspace"]');
      if (json) json.setAttribute('hidden', '');
      if (category) category.setAttribute('hidden', '');
      if (dashboard) dashboard.removeAttribute('hidden');
      const workspace = document.querySelector('[data-role="tool-workbench"]');
      if (workspace) workspace.setAttribute('data-view', 'dashboard');
    },
    formatJsonAction: ({ document }) => {
      const input = document.querySelector('[data-role="tool-json-input"]') as HTMLTextAreaElement | null;
      const result = document.querySelector('[data-role="tool-json-result"]');
      if (!input || !result) return;
      const payload = formatJson(input.value);
      result.setAttribute('data-state', payload.state);
      result.textContent = resultMessageHtml(payload).replace(/&#10;/g, '\n');
      if (payload.output && payload.state === 'success') {
        result.textContent = '';
        const pre = document.createElement('pre');
        pre.textContent = payload.output;
        pre.setAttribute('class', 'json-pre wb-pre');
        result.appendChild(pre);
      }
    },
    openCategory: ({ document, element }) => {
      const key = element.getAttribute('data-tool-category') as ToolCategoryKey | null;
      if (!key) return;
      const dashboard = document.querySelector('[data-role="tool-dashboard"]');
      if (dashboard) dashboard.setAttribute('hidden', '');
      const workspace = document.querySelector('[data-role="tool-category-workspace"]');
      if (workspace) {
        workspace.setAttribute('data-tool-category', key);
        workspace.removeAttribute('hidden');
      }
      const bench = document.querySelector('[data-role="tool-workbench"]');
      if (bench) bench.setAttribute('data-view', key);
    },
    runCategoryAction: ({ document }) => {
      const workspace = document.querySelector('[data-role="tool-category-workspace"]') as HTMLElement | null;
      const category = (workspace?.getAttribute('data-tool-category') || '') as ToolCategoryKey;
      const result = workspace?.querySelector('[data-role="tool-category-result"]') as HTMLElement | null;
      if (!workspace || !result) return;
      let payload: ResultPayload;
      if (category === 'text') {
        const input = workspace.querySelector('[data-role="tool-category-input"]') as HTMLTextAreaElement | null;
        const select = workspace.querySelector('select') as HTMLSelectElement | null;
        const text = input?.value ?? '';
        if (!text.trim()) {
          payload = { state: 'error', message: 'Enter some text to transform.' };
        } else {
          const transform = (select?.value as 'upper' | 'lower' | 'title') || 'upper';
          const transformed = transformText(text, transform);
          const counts = countText(text);
          payload = {
            state: 'success',
            message: `${counts.characters} characters, ${counts.words} words`,
            output: transformed,
          };
        }
      } else if (category === 'data') {
        const input = workspace.querySelector('[data-role="tool-category-input"]') as HTMLTextAreaElement | null;
        const select = workspace.querySelector('select') as HTMLSelectElement | null;
        payload = runDataOperation(input?.value ?? '', (select?.value as 'json' | 'encode' | 'decode') || 'json');
      } else if (category === 'seo') {
        const input = workspace.querySelector('[data-role="tool-category-input"]') as HTMLTextAreaElement | null;
        payload = analyzeHtml(input?.value ?? '');
      } else if (category === 'images') {
        const input = workspace.querySelector('[data-role="tool-category-input"]') as HTMLTextAreaElement | null;
        payload = inspectMedia(input?.value ?? '');
      } else {
        const input = workspace.querySelector('[data-role="tool-category-input"]') as HTMLTextAreaElement | null;
        const title = (workspace.querySelector('[name="title"]') as HTMLInputElement | null)?.value ?? '';
        const description = (workspace.querySelector('[name="description"]') as HTMLTextAreaElement | null)?.value ?? '';
        const url = (workspace.querySelector('[name="url"]') as HTMLInputElement | null)?.value ?? '';
        const fallback = parseSocialInputs(input?.value ?? '');
        if (fallback.state === 'success') {
          const fb = fallback.output as { title?: string; description?: string; url?: string };
          const inputs: SocialInputs = {
            title: title || (fb.title ?? ''),
            description: description || (fb.description ?? ''),
            url: url || (fb.url ?? ''),
          };
          payload = socialPreview(inputs);
        } else {
          payload = fallback;
        }
      }
      result.setAttribute('data-state', payload.state);
      result.textContent = '';
      const pre = document.createElement('pre');
      pre.textContent = payload.output ? `${payload.message}\n\n${payload.output}` : payload.message;
      pre.setAttribute('class', 'cat-pre wb-pre');
      result.appendChild(pre);
    },
    categoryBack: ({ document }) => {
      const dashboard = document.querySelector('[data-role="tool-dashboard"]');
      const category = document.querySelector('[data-role="tool-category-workspace"]');
      if (category) category.setAttribute('hidden', '');
      if (dashboard) dashboard.removeAttribute('hidden');
      const workspace = document.querySelector('[data-role="tool-workbench"]');
      if (workspace) workspace.setAttribute('data-view', 'dashboard');
    },
    filterLibrary: ({ document, element }) => {
      const input = element as HTMLInputElement;
      const rows = document.querySelectorAll('[data-role="tool-library-row"]');
      const query = input.value.trim().toLowerCase();
      rows.forEach((row) => {
        const label = (row.getAttribute('data-label') || '').toLowerCase();
        (row as HTMLElement).toggleAttribute('hidden', query !== '' && !label.includes(query));
      });
    },
  },
  bindings: [
    { selector: '[data-role="tool-library-button"]', event: 'click', handler: 'openLibrary' },
    { selector: '[data-role="tool-library-close"]', event: 'click', handler: 'closeLibrary' },
    { selector: '[data-role="tool-space-button"]', event: 'click', handler: 'openSpace' },
    { selector: '[data-role="tool-space-close"]', event: 'click', handler: 'closeSpace' },
    { selector: '[data-role="tool-card-json"]', event: 'click', handler: 'openJson' },
    { selector: '[data-role="tool-open-json"]', event: 'click', handler: 'openJson' },
    { selector: '[data-role="tool-back-dashboard"]', event: 'click', handler: 'backDashboard' },
    { selector: '[data-role="tool-format-json"]', event: 'click', handler: 'formatJsonAction' },
    { selector: '[data-role^="tool-card-"]:not([data-role="tool-card-json"])', event: 'click', handler: 'openCategory' },
    { selector: '[data-role="tool-category-action"]', event: 'click', handler: 'runCategoryAction' },
    { selector: '[data-role="tool-category-back"]', event: 'click', handler: 'categoryBack' },
    { selector: '[data-role="tool-search"]', event: 'input', handler: 'filterLibrary' },
  ],
});

