.shell {
  --ink: #0f2a2c;
  --ink-soft: #16393b;
  --ink-deep: #0a1d1f;
  --ivory: #f6f1e6;
  --ivory-soft: #ece4d4;
  --paper: #fbf8f0;
  --line: rgba(232, 224, 204, 0.18);
  --text-bright: #f4f0e6;
  --text-soft: #b8c4bf;
  --teal: #2c6b65;
  --teal-bright: #4f9a91;
  --warm: #e8c88a;

  color: var(--text-bright);
  font-family: 'Segoe UI', system-ui, sans-serif;
  line-height: 1.5;
}

@keyframes wb-lift {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes wb-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.wb-card {
  background: var(--ink-soft);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 16px;
}

.wb-folder {
  border-radius: 14px;
  border: 1px solid var(--line);
  padding: 20px 16px;
  text-align: left;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.wb-folder:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.28);
}

.wb-folder-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 44px;
  border-radius: 10px;
  font-weight: 700;
  font-size: 18px;
  margin-bottom: 14px;
}

.wb-folder-title {
  display: block;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-bright);
}

.wb-folder-blurb {
  display: block;
  margin-top: 4px;
  font-size: 12px;
  color: var(--text-soft);
}

.wb-brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--warm);
}

.wb-brand-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
