  font-size: 26px;
  font-weight: 700;
  color: var(--text-bright);
}

.wb-subheading {
  margin: 0;
  font-size: 14px;
  color: var(--text-soft);
}

.wb-label {
  display: block;
  margin-bottom: 6px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-soft);
}

.wb-textarea {
  width: 100%;
  min-height: 160px;
  resize: vertical;
  border-radius: 10px;
  border: 1px solid var(--line);
  padding: 12px;
  font-family: 'Consolas', 'Menlo', monospace;
  font-size: 13px;
  background: var(--paper);
  color: var(--ink);
}

.wb-editor-area {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px;
}

.wb-result-surface {
  border-radius: 12px;
  border: 1px solid var(--line);
  background: var(--ivory-soft);
  padding: 14px;
  min-height: 96px;
  font-size: 13px;
}

.wb-result-surface[data-state='idle'] {
