function folderIcon(key: string): string {
  switch (key) {
    case 'text':
      return 'T';
    case 'data':
      return '{ }';
    case 'seo':
      return '</>';
    case 'images':
      return '#';
    case 'social':
      return '+';
    default:
      return '•';
  }
}

