import type { ViewState, ResultState } from '../../shared/types';

export interface JsonWorkspaceProps {
  readonly state: ViewState;
  readonly resultState: ResultState;
  readonly resultMessage: string;
  readonly formatted: string;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function renderJsonWorkspace(props: JsonWorkspaceProps): string {
  const { resultState, resultMessage, formatted } = props;

  const inputId = 'wb-json-input';
  const resultId = 'wb-json-result';

  return `
    <div class="json-workspace workspace" data-role="tool-workspace">
      <div class="json-head">
        <button type="button" class="json-back wb-btn" data-role="tool-back-dashboard" aria-label="Back to dashboard">&larr; Dashboard</button>
        <div>
          <h1 class="json-title wb-heading">JSON Formatter</h1>
          <p class="json-sub wb-subheading">Paste JSON, format it locally, and inspect the result.</p>
        </div>
      </div>

      <form class="json-form pure-form pure-form-stacked" novalidate>
        <label class="json-input-label wb-label" for="${inputId}">JSON input</label>
        <div class="json-input-area wb-editor-area">
          <textarea
            id="${inputId}"
            class="json-input wb-textarea"
            data-role="tool-json-input"
            rows="12"
            spellcheck="false"
            placeholder='{"name":"web-tools","version":"1.0.0"}'
          >{"name":"web-tools","version":"1.0.0","ready":true}</textarea>
        </div>

        <div class="json-actions">
          <button type="button" class="pure-button pure-button-primary json-btn wb-btn-primary" data-role="tool-format-json">Format JSON</button>
          <span class="json-status" aria-live="polite">${resultMessage ? escapeHtml(resultMessage) : 'Ready. JSON stays in this browser.'}</span>
        </div>
      </form>

      <div class="json-result-wrap">
        <span class="json-result-label wb-label" id="${resultId}-label">Formatted result</span>
        <div class="json-result result wb-result-surface" data-role="tool-json-result" data-state="${resultState}" aria-labelledby="${resultId}-label" aria-live="polite">
          ${formatted
            ? `<pre class="json-pre wb-pre">${escapeHtml(formatted)}</pre>`
            : resultState === 'error'
              ? `<p class="json-msg">${escapeHtml(resultMessage)}</p>`
              : `<p class="json-msg">Run Format JSON to see the pretty-printed object here.</p>`}
        </div>
      </div>
    </div>
  `;
}

export default renderJsonWorkspace;

