import type { ResultState, ToolCategoryKey } from '../../shared/types';
import { CATEGORY_TITLE } from '../../shared/types';

export interface CategoryWorkspaceProps {
  readonly category: ToolCategoryKey;
  readonly resultState: ResultState;
  readonly resultMessage: string;
  readonly resultOutput?: string;
}

const SELECT_OPTIONS: Record<ToolCategoryKey, ReadonlyArray<readonly [string, string]> | null> = {
  text: [
    ['upper', 'Uppercase'],
    ['lower', 'Lowercase'],
    ['title', 'Title case'],
  ],
  data: [
    ['json', 'Format JSON'],
    ['encode', 'Encode URL'],
    ['decode', 'Decode URL'],
  ],
  seo: null,
  images: null,
  social: null,
};

const CATEGORY_BLURB: Record<ToolCategoryKey, string> = {
  text: 'Convert case and count characters and words.',
  data: 'Format JSON and encode or decode URL text.',
  seo: 'Check title, description, headings, links, and image alt coverage.',
  images: 'Inspect data URLs or SVG text for type, size, and dimensions.',
  social: 'Build a local social preview from title, description, and URL.',
};

const ACTION_LABEL: Record<ToolCategoryKey, string> = {
  text: 'Run text tool',
  data: 'Run data tool',
  seo: 'Analyze HTML',
  images: 'Inspect media',
  social: 'Generate preview',
};

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function buildSelect(category: ToolCategoryKey): string {
  const options = SELECT_OPTIONS[category];
  if (!options) return '';
  const inputId = 'cat-select';
  const choices = options
    .map(([value, label]) => `          <option value="${value}">${label}</option>`)
    .join('\n');
  return `
      <div class="cat-field">
        <label class="cat-label" for="${inputId}">Operation</label>
        <select class="cat-select" id="${inputId}" name="operation">
${choices}
        </select>
      </div>`;
}

function buildFields(category: ToolCategoryKey): string {
  if (category === 'social') {
    return `
      <div class="cat-field">
        <label class="cat-label" for="cat-primary">JSON or first field</label>
        <input class="cat-input" id="cat-primary" type="text" data-role="tool-category-input"
          placeholder='{"title":"...","description":"...","url":"https://..."}' />
      </div>
      <div class="cat-field">
        <label class="cat-label" for="cat-title">Title</label>
        <input class="cat-input" id="cat-title" type="text" name="title" placeholder="Post title" />
      </div>
      <div class="cat-field">
        <label class="cat-label" for="cat-description">Description</label>
        <textarea class="cat-textarea" id="cat-description" name="description" rows="3" placeholder="Short description"></textarea>
      </div>
      <div class="cat-field">
        <label class="cat-label" for="cat-url">URL</label>
        <input class="cat-input" id="cat-url" type="text" name="url" placeholder="https://example.com/post" />
      </div>`;
  }

  if (category === 'seo') {
    return `
      <div class="cat-field">
        <label class="cat-label" for="cat-primary">HTML source</label>
        <textarea class="cat-textarea" id="cat-primary" data-role="tool-category-input" rows="10"
          placeholder="<title>My page</title>"></textarea>
      </div>`;
  }

  if (category === 'images') {
    return `
      <div class="cat-field">
        <label class="cat-label" for="cat-primary">Data URL or SVG text</label>
        <textarea class="cat-textarea" id="cat-primary" data-role="tool-category-input" rows="8"
          placeholder="data:image/svg+xml,...</textarea>
      </div>`;
  }

  return `
      <div class="cat-field">
        <label class="cat-label" for="cat-primary">Input</label>
        <textarea class="cat-textarea" id="cat-primary" data-role="tool-category-input" rows="8"
          placeholder="Enter text here"></textarea>
      </div>`;
}

export function renderCategoryWorkspace(props: CategoryWorkspaceProps): string {
  const { category, resultState, resultMessage, resultOutput } = props;
  const title = CATEGORY_TITLE[category];
  const blurb = CATEGORY_BLURB[category];
  const actionLabel = ACTION_LABEL[category];

  const selectMarkup = buildSelect(category);
  const fieldsMarkup = buildFields(category);

  const resultContent = resultOutput
    ? `<pre class="cat-result-pre">${escapeHtml(resultOutput)}</pre>`
    : (resultMessage ? escapeHtml(resultMessage) : 'Result appears after running the tool.');

  return `
    <div class="cat-workspace workspace" data-role="tool-category-workspace" data-tool-category="${category}">
      <div class="cat-head">
        <button type="button" class="cat-back" data-role="tool-category-back" aria-label="Back to dashboard">&larr; Dashboard</button>
        <div>
          <h1 class="cat-title">${title}</h1>
          <p class="cat-sub">${blurb}</p>
        </div>
      </div>

      <form class="cat-form pure-form pure-form-stacked" novalidate>
        ${fieldsMarkup}
        ${selectMarkup}
        <div class="cat-actions">
          <button type="button" class="pure-button pure-button-primary cat-btn-primary" data-role="tool-category-action">${actionLabel}</button>
          <span class="cat-status" aria-live="polite"></span>
        </div>
      </form>

      <div class="cat-result" data-role="tool-category-result" data-state="${resultState}">
        ${resultContent}
      </div>
    </div>`;
}

export default renderCategoryWorkspace;

