import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  countText,
  titleCase,
  transformText,
} from '../tools/logic';

test('countText reports characters and words', () => {
  assert.deepEqual(countText('hello world'), {
    characters: 11,
    words: 2,
  });
});

test('countText handles empty and whitespace input', () => {
  assert.deepEqual(countText(''), { characters: 0, words: 0 });
  assert.deepEqual(countText('   '), { characters: 3, words: 0 });
});

test('titleCase capitalizes words and skips empties', () => {
  assert.equal(titleCase('hello world'), 'Hello World');
  assert.equal(titleCase('  web  tools  '), 'Web Tools');
  assert.equal(titleCase(''), '');
});

test('transformText applies each transform', () => {
  assert.equal(transformText('Hello World', 'upper'), 'HELLO WORLD');
  assert.equal(transformText('Hello World', 'lower'), 'hello world');
  assert.equal(transformText('hello world', 'title'), 'Hello World');
});

test('transformText returns empty string for empty input', () => {
  assert.equal(transformText('', 'upper'), '');
  assert.equal(transformText('', 'lower'), '');
  assert.equal(transformText('', 'title'), '');
});

test('transformText preserves internal whitespace on upper and lower', () => {
  assert.equal(transformText('a  b', 'upper'), 'A  B');
  assert.equal(transformText('a  b', 'lower'), 'a  b');
});

