  const formatted = '{\n  "ready": true\n}';
  const payload = formatJson(formatted);
  assert.equal(payload.state, 'success');
  assert.equal(payload.output, formatted);
});

test('formatJson reports a helpful error for malformed JSON', () => {
  const payload = formatJson('{"name": web-tools,}');
  assert.equal(payload.state, 'error');
  assert.match(payload.message, /Unexpected|Invalid|Expected/);
});

test('formatJson reports a helpful error for empty input', () => {
  const payload = formatJson('');
  assert.equal(payload.state, 'error');
  assert.match(payload.message, /empty|Enter|No JSON/i);
});

