import { test } from 'node:test';
import assert from 'node:assert/strict';
import { analyzeHtml } from '../tools/logic';

test('analyzeHtml finds title and description', () => {
  const html = `
    <html>
      <head>
        <title>My Page</title>
        <meta name="description" content="About my page" />
      </head>
      <body><h1>Header</h1></body>
    </html>
  `;
  const payload = analyzeHtml(html);
  assert.equal(payload.state, 'success');
  assert.ok(payload.message.includes('My Page'));
  assert.ok(payload.message.includes('About my page'));
});

test('analyzeHtml reports missing title and description as error-like details but success overall', () => {
  const payload = analyzeHtml('<div>No head</div>');
  assert.equal(payload.state, 'success');
  assert.ok(payload.message.toLowerCase().includes('title'));
  assert.ok(payload.message.toLowerCase().includes('description'));
});

test('analyzeHtml counts headings h1 h2 h3', () => {
  const html = `
    <h1>One</h1>
    <h2>Two</h2>
    <h2>Three</h2>
    <h3>Four</h3>
    <h4>Five</h4>
  `;
  const payload = analyzeHtml(html);
  assert.equal(payload.state, 'success');
  assert.ok(payload.message.includes('1'));
  assert.ok(payload.message.includes('2'));
  assert.ok(payload.message.includes('1'));
});

test('analyzeHtml counts links', () => {
  const html = `
    <a href="/a">A</a>
    <a href="/b">B</a>
    <a href="/c">C</a>
  `;
  const payload = analyzeHtml(html);
  assert.equal(payload.state, 'success');
  assert.ok(payload.message.includes('3'));
});

test('analyzeHtml reports image alt coverage', () => {
  const html = `
    <img src="a.png" alt="Image A" />
    <img src="b.png" alt="Image B" />
    <img src="c.png" />
  `;
  const payload = analyzeHtml(html);
  assert.equal(payload.state, 'success');
  assert.ok(payload.message.includes('3'));
  assert.ok(payload.message.includes('2'));
});

test('analyzeHtml handles empty input with error state', () => {
  const payload = analyzeHtml('');
  assert.equal(payload.state, 'error');
  assert.ok(payload.message.length > 0);
});

test('analyzeHtml handles malformed html without throwing', () => {
  const payload = analyzeHtml('<unclosed><div><span>text');
