import type {
  ResultPayload,
  SocialInputs,
  ToolCategoryKey,
} from '../../shared/types';

export interface TextCounts {
  readonly characters: number;
  readonly words: number;
}

export type TextTransform = 'upper' | 'lower' | 'title';

export function countText(text: string): TextCounts {
  const trimmed = text.trim();
  const words = trimmed.length > 0 ? trimmed.split(/\s+/).length : 0;
  return {
    characters: text.length,
    words,
  };
}

export function titleCase(text: string): string {
  return text.replace(/\S+/g, (word) => {
    if (word.length === 0) return word;
    return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
  });
}

export function transformText(text: string, transform: TextTransform): string {
  switch (transform) {
    case 'upper':
      return text.toUpperCase();
    case 'lower':
      return text.toLowerCase();
    case 'title':
      return titleCase(text);
  }
}

export function formatJson(input: string): ResultPayload {
  const trimmed = input.trim();
  if (!trimmed) {
    return { state: 'error', message: 'Paste JSON to format before running the tool.' };
  }
  try {
    const value: unknown = JSON.parse(trimmed);
    return {
      state: 'success',
      message: 'JSON is valid and formatted with two-space indentation.',
      output: JSON.stringify(value, null, 2),
    };
  } catch (error) {
    const reason = error instanceof Error ? error.message : 'Invalid JSON';
    return {
      state: 'error',
      message: `JSON is not valid: ${reason}`,
    };
  }
}

export type DataOperation = 'json' | 'encode' | 'decode';

export function runDataOperation(input: string, operation: DataOperation): ResultPayload {
  if (operation === 'json') {
    return formatJson(input);
  }
  if (!input) {
    return { state: 'error', message: 'Paste text before encoding or decoding a URL query.' };
  }
  try {
    if (operation === 'encode') {
      return {
        state: 'success',
        message: 'Encoded the query text for use in a URL.',
        output: encodeURIComponent(input),
      };
    }
    return {
      state: 'success',
      message: 'Decoded the query text from percent-encoding.',
      output: decodeURIComponent(input),
    };
  } catch (error) {
    const reason = error instanceof Error ? error.message : 'Invalid input';
    return {
      state: 'error',
      message: `${operation === 'encode' ? 'Encoding' : 'Decoding'} failed: ${reason}`,
    };
  }
}

export interface SeoReport {
  readonly hasTitle: boolean;
  readonly title: string;
  readonly hasDescription: boolean;
  readonly description: string;
  readonly headingCounts: Record<'h1' | 'h2' | 'h3', number>;
  readonly linkCount: number;
  readonly imageCount: number;
  readonly imageAltCount: number;
  readonly imageAltCoverage: number;
}

function extractMetaContent(html: string, property: string): string {
  const patterns: Array<RegExp> = [
    new RegExp(`<meta[^>]+name=["']${property}["'][^>]+content=["']([^"']*)["']`, 'i'),
    new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]+name=["']${property}["']`, 'i'),
  ];
  for (const pattern of patterns) {
    const match = html.match(pattern);
    if (match && match[1]) return match[1].trim();
  }
  return '';
}

export function analyzeHtml(html: string): ResultPayload {
  const trimmed = html.trim();
  if (!trimmed) {
    return { state: 'error', message: 'Paste HTML markup to audit before running the tool.' };
  }

  const titleMatch = trimmed.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const title = titleMatch ? titleMatch[1].replace(/\s+/g, ' ').trim() : '';
  const description = extractMetaContent(trimmed, 'description');

  const headingCounts: SeoReport['headingCounts'] = { h1: 0, h2: 0, h3: 0 };
  for (const level of ['h1', 'h2', 'h3'] as const) {
    const headingMatches = trimmed.match(new RegExp(`<${level}(?:\\s[^>]*)?>[\\s\\S]*?<\\/${level}>`, 'gi'));
    headingCounts[level] = headingMatches ? headingMatches.length : 0;
  }

  const linkMatches = trimmed.match(/<a(?:\s[^>]*)?href=["'][^"']+["'][^>]*>/gi);
  const imageMatches = trimmed.match(/<img(?:\s[^>]*)?\/?>/gi);
  const imageCount = imageMatches ? imageMatches.length : 0;
  let imageAltCount = 0;
  if (imageMatches) {
    for (const img of imageMatches) {
      const altMatch = img.match(/alt=["']([^"']*)["']/i);
      if (altMatch && altMatch[1].trim()) {
        imageAltCount += 1;
      }
    }
  }

  const imageAltCoverage = imageCount > 0 ? imageAltCount / imageCount : 1;
  const report: SeoReport = {
    hasTitle: title.length > 0,
    title,
    hasDescription: description.length > 0,
    description,
    headingCounts,
    linkCount: linkMatches ? linkMatches.length : 0,
    imageCount,
    imageAltCount,
    imageAltCoverage,
  };

  const lines = [
    `Title: ${report.hasTitle ? report.title : '(missing)'}`,
    `Description: ${report.hasDescription ? report.description : '(missing)'}`,
    `H1: ${headingCounts.h1} | H2: ${headingCounts.h2} | H3: ${headingCounts.h3}`,
    `Links: ${report.linkCount}`,
    `Images: ${report.imageCount} total, ${report.imageAltCount} with alt text (${Math.round(report.imageAltCoverage * 100)}% coverage)`,
  ];

  const missing: string[] = [];
  if (!report.hasTitle) missing.push('title');
  if (!report.hasDescription) missing.push('meta description');
  if (headingCounts.h1 === 0) missing.push('H1 heading');
  if (report.imageCount > 0 && report.imageAltCoverage < 1) missing.push('complete image alt coverage');

  const summary = missing.length > 0
    ? `Audit finished; attention needed for ${missing.join(', ')}.`
    : 'Audit finished; core on-page signals are present.';

  return {
    state: 'success',
    message: summary,
    output: lines.join('\n'),
  };
}

export interface MediaReport {
  readonly type: string;
  readonly width?: number;
  readonly height?: number;
  readonly byteLength: number;
}

const DATA_URL_RE = /^data:([^;,]+)/;

function base64ByteLength(body: string): number {
  const clean = body.replace(/\s+/g, '');
  const pad = clean.endsWith('==') ? 2 : clean.endsWith('=') ? 1 : 0;
  return Math.floor((clean.length * 3) / 4) - pad;
}

function decodeBase64(body: string): string {
  try {
    if (typeof atob === 'function') {
      return atob(body);
    }
  } catch {
    return '';
  }
  return '';
}

export function inspectMedia(input: string): ResultPayload {
  const trimmed = input.trim();
  if (!trimmed) {
    return { state: 'error', message: 'Paste a data URL or SVG markup to inspect.' };
  }

  if (trimmed.startsWith('data:')) {
    const headerMatch = trimmed.match(DATA_URL_RE);
    const mediaType = headerMatch ? headerMatch[1].split(';')[0].trim() : 'unknown';
    const commaIndex = trimmed.indexOf(',');
    if (commaIndex === -1) {
      return { state: 'error', message: 'Data URL is missing a payload after the header.' };
    }
    const body = trimmed.slice(commaIndex + 1);
    const isBase64 = /;base64/i.test(trimmed);
    const byteLength = isBase64 ? base64ByteLength(body) : body.length;

    if (/^image\/svg\+xml$/i.test(mediaType)) {
      const svgSource = isBase64 ? decodeBase64(body) : body;
      const dims = extractSvgDimensions(svgSource);
      const report: MediaReport = { type: 'SVG (data URL)', byteLength, ...dims };
      return {
        state: 'success',
        message: `Detected ${report.type} payload${dims.width ? ` with ${dims.width}x${dims.height}px dimensions` : ''}.`,
        output: formatReport(report),
      };
    }

    if (isBase64 && /^(image\/(png|jpeg|jpg|gif|webp|bmp))/i.test(mediaType)) {
      const dims = decodeRasterDimensions(body);
      const report: MediaReport = { type: mediaType, byteLength, ...dims };
      return {
        state: 'success',
        message: `Detected ${report.type} payload${dims.width ? ` with ${dims.width}x${dims.height}px dimensions` : ''}.`,
        output: formatReport(report),
      };
    }

    const report: MediaReport = { type: mediaType || 'generic data URL', byteLength };
    return {
      state: 'success',
      message: `Detected a ${report.type} data URL.`,
      output: formatReport(report),
    };
  }

  const svgMatch = trimmed.match(/<svg[^>]*>/i);
  if (svgMatch) {
    const dims = extractSvgDimensions(trimmed);
    const report: MediaReport = { type: 'SVG (inline markup)', byteLength: trimmed.length, ...dims };
    return {
      state: 'success',
      message: `Detected inline SVG markup${dims.width ? ` with ${dims.width}x${dims.height}px dimensions` : ''}.`,
      output: formatReport(report),
    };
  }

  return { state: 'error', message: 'No data URL or SVG markup detected in the input.' };
}

function extractSvgDimensions(source: string): { width?: number; height?: number } {
  const widthMatch = source.match(/width=["'](\d+(?:\.\d+)?)\s*(?:px)?["']/i)
    || source.match(/width\s*=\s*["']?(\d+(?:\.\d+)?)["']?/i);
  const heightMatch = source.match(/height=["'](\d+(?:\.\d+)?)\s*(?:px)?["']/i)
    || source.match(/height\s*=\s*["']?(\d+(?:\.\d+)?)["']?/i);
  const width = widthMatch ? Math.round(Number(widthMatch[1])) : undefined;
  const height = heightMatch ? Math.round(Number(heightMatch[1])) : undefined;
  if (width !== undefined && Number.isFinite(width)) {
    return width !== undefined && height !== undefined ? { width, height } : { width };
  }
  if (height !== undefined && Number.isFinite(height)) return { height };
  return {};
}

function decodeRasterDimensions(body: string): { width?: number; height?: number } {
  const decoded = decodeBase64(body);
  if (decoded.length >= 24) {
    const chars = decoded.slice(0, 24);
    if (
      (chars.charCodeAt(0) === 0x89 && chars.charCodeAt(1) === 0x50 &&
       chars.charCodeAt(2) === 0x4e && chars.charCodeAt(3) === 0x47)
    ) {
      const width = ((chars.charCodeAt(16) << 24) | (chars.charCodeAt(17) << 16) |
                     (chars.charCodeAt(18) << 8) | chars.charCodeAt(19)) >>> 0;
      const height = ((chars.charCodeAt(20) << 24) | (chars.charCodeAt(21) << 16) |
                      (chars.charCodeAt(22) << 8) | chars.charCodeAt(23)) >>> 0;
      if (width > 0 && height > 0) return { width, height };
    }
    if (
      chars.charCodeAt(0) === 0xff && chars.charCodeAt(1) === 0xd8 &&
      chars.charCodeAt(2) === 0xff
    ) {
      return parseJpegDimensions(decoded);
    }
  }
  return {};
}

function parseJpegDimensions(source: string): { width?: number; height?: number } {
  if (source.length < 4) return {};
  let offset = 2;
  while (offset + 9 < source.length) {
    const marker = (source.charCodeAt(offset) << 8) | source.charCodeAt(offset + 1);
    offset += 2;
    if (marker === 0xd8) continue;
    if ((marker & 0xff00) !== 0xff00) return {};
    if (marker >= 0xd0 && marker <= 0xd7) {
      offset += 2;
      continue;
    }
    if (offset + 2 > source.length) return {};
    const length = (source.charCodeAt(offset) << 8) | source.charCodeAt(offset + 1);
    if (length < 2) return {};
    if (marker === 0xc0 || marker === 0xc2) {
      if (offset + 7 > source.length) return {};
      const height = (source.charCodeAt(offset + 5) << 8) | source.charCodeAt(offset + 6);
      const width = (source.charCodeAt(offset + 7) << 8) | source.charCodeAt(offset + 8);
      return { width, height };
    }
    offset += length;
  }
  return {};
}

function formatReport(report: MediaReport): string {
  const lines = [
    `Type: ${report.type}`,
    `Size: ${report.byteLength} bytes`,
  ];
  if (report.width !== undefined && report.height !== undefined) {
    lines.push(`Dimensions: ${report.width}x${report.height}px`);
  } else {
    lines.push('Dimensions: not detected');
  }
  return lines.join('\n');
}

export function parseSocialInputs(input: string): ResultPayload {
  const trimmed = input.trim();
  if (!trimmed) {
    return { state: 'error', message: 'Provide a title, description, and URL to preview.' };
  }
  if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
    try {
      const parsed: unknown = JSON.parse(trimmed);
      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
        const obj = parsed as Record<string, unknown>;
        const title = typeof obj.title === 'string' ? obj.title : '';
        const description = typeof obj.description === 'string' ? obj.description : '';
        const url = typeof obj.url === 'string' ? obj.url : '';
        return socialPreview({ title, description, url });
      }
    } catch {
      /* fall through to field parsing */
    }
  }

  const fields = parseKeyValueInput(trimmed);
  const title = fields.get('title') ?? '';
  const description = fields.get('description') ?? '';
  const url = fields.get('url') ?? '';
  return socialPreview({ title, description, url });
}

function parseKeyValueInput(input: string): Map<string, string> {
  const map = new Map<string, string>();
  const lines = input.split(/\r?\n/);
  for (const line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex > 0) {
      const key = line.slice(0, colonIndex).trim().toLowerCase();
      const value = line.slice(colonIndex + 1).trim();
      map.set(key, value);
    } else if (line.includes('=')) {
      const eqIndex = line.indexOf('=');
      const key = line.slice(0, eqIndex).trim().toLowerCase();
      const value = line.slice(eqIndex + 1).trim();
      map.set(key, value);
    }
  }
  return map;
}

export function socialPreview(inputs: SocialInputs): ResultPayload {
  const title = inputs.title.trim();
  const description = inputs.description.trim();
  const url = inputs.url.trim();

  if (!title && !description && !url) {
    return { state: 'error', message: 'Provide at least a title, description, or URL to preview.' };
  }

  if (url) {
    try {
      // Local-only validation: ensure the URL is syntactically parseable.
      const parsed = new URL(url);
      if (!parsed.protocol || !['http:', 'https:'].includes(parsed.protocol)) {
        return {
          state: 'error',
          message: 'URL must use http:// or https:// (no network fetch is performed).',
        };
      }
    } catch {
      return { state: 'error', message: 'URL could not be parsed locally. Check the format.' };
    }
  }

  const displayTitle = title || '(untitled)';
  const displayDescription = description || '(no description)';
  const displayUrl = url || '(no URL)';

  const lines = [
    `Title: ${displayTitle}`,
    `Description: ${displayDescription}`,
    `URL: ${displayUrl}`,
    `Title length: ${title.length} characters${title.length > 0 && title.length > 60 ? ' (consider shortening to 60 or fewer)' : ''}`,
    `Description length: ${description.length} characters${description.length > 0 && description.length > 160 ? ' (consider shortening to 160 or fewer)' : ''}`,
    'Preview is generated locally; no request is made to the URL.',
  ];

  return {
    state: 'success',
    message: 'Social preview generated from local fields.',
    output: lines.join('\n'),
  };
}

