import type { ToolCategoryKey } from '../../shared/types';
import { CATEGORY_META } from '../../shared/types';

export interface LibraryRenderProps {
  readonly open: boolean;
}

export const filterLibraryTools = (query: string): readonly ToolCategoryKey[] => {
  const q = query.trim().toLowerCase();
  if (!q) return CATEGORY_META.map((c) => c.key);
  return CATEGORY_META.filter(
    (c) =>
      c.title.toLowerCase().includes(q) ||
      c.blurb.toLowerCase().includes(q) ||
      c.key.toLowerCase().includes(q),
  ).map((c) => c.key);
};

export function renderLibrary(props: LibraryRenderProps): string {
  const open = props.open;
  const state = open ? 'open' : 'closed';
  const visible = filterLibraryTools('');

  const rows = visible
    .map((key) => {
      const meta = CATEGORY_META.find((m) => m.key === key);
      if (!meta) return '';
      return `
        <div class="library-row" data-category="${meta.key}">
          <span class="library-row-text">
            <strong>${meta.title}</strong>
            <span class="library-row-sub">${meta.blurb}</span>
          </span>
        </div>`;
    })
    .join('');

  const filters = CATEGORY_META
    .map(
      (m) =>
        `<button type="button" class="library-filter" data-filter="${m.key}" aria-pressed="false">${m.title}</button>`,
    )
    .join('');

  return `
    <div class="library" data-role="tool-library" data-state="${state}" aria-hidden="${!open}">
      <div class="library-header">
        <h2 class="library-title">Tool Library</h2>
        <button type="button" class="library-close" data-role="tool-library-close" aria-label="Close library">&times;</button>
      </div>
      <div class="library-search-wrap">
        <input
          type="search"
          class="library-search"
          data-role="tool-search"
          placeholder="Search tools…"
          aria-label="Search tools"
        />
      </div>
      <div class="library-filters" role="group" aria-label="Category filters">${filters}</div>
      <div class="library-rows">${rows}</div>
      <div class="library-quick">
        <button type="button" class="library-open-json" data-role="tool-open-json">JSON Formatter</button>
      </div>
      <div class="library-empty" hidden>No tools match your search.</div>
    </div>`;
}

export default renderLibrary;

