import type { ViewState } from '../../shared/types';
import { CATEGORY_META } from '../../shared/types';

export interface PersonalSpaceRenderProps {
  readonly open: boolean;
}

interface SavedTool {
  readonly name: string;
  readonly tag: string;
  readonly icon: string;
}

const SAVED_TOOLS: readonly SavedTool[] = [
  { name: 'JSON Formatter', tag: 'Quick access', icon: '{ }' },
  { name: 'Web & SEO', tag: 'Favourite', icon: '</>' },
  { name: 'Development & Data', tag: 'Favourite', icon: '{ }' },
];

const RECENT_TOOLS: readonly SavedTool[] = [
  { name: 'Text & Content', tag: 'Recently used', icon: 'T' },
  { name: 'Social & Platforms', tag: 'Recently used', icon: '+' },
  { name: 'Images & Media', tag: 'Recently used', icon: '#' },
];

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function toolRow(tool: SavedTool): string {
  return `
        <div class="space-row">
          <span class="space-row-icon" aria-hidden="true">${escapeHtml(tool.icon)}</span>
          <span class="space-row-name">${escapeHtml(tool.name)}</span>
          <span class="space-row-tag">${escapeHtml(tool.tag)}</span>
        </div>`;
}

export function renderPersonalSpace(props: PersonalSpaceRenderProps): string {
  const { open } = props;
  const state = open ? 'open' : 'closed';

  const savedRows = SAVED_TOOLS.map(toolRow).join('\n');
  const recentRows = RECENT_TOOLS.map(toolRow).join('\n');

  return `
    <div class="space-dialog library" data-role="tool-space-dialog" data-state="${state}" aria-hidden="${open ? 'false' : 'true'}">
      <div class="space-sheet card">
        <div class="space-header">
          <h2 class="space-title wb-heading">My Space</h2>
          <button type="button" class="space-close wb-btn" data-role="tool-space-close" aria-label="Close personal space">Close</button>
        </div>

        <div class="space-tabs" role="tablist" aria-label="Space sections">
          <span class="space-tab" data-state="active" role="tab">Saved &amp; Favourites</span>
          <span class="space-tab" role="tab">Recent</span>
        </div>

        <div class="space-section">
          <h3 class="space-section-title wb-subheading">Saved &amp; Favourites</h3>
          <div class="space-rows">
${savedRows}
          </div>
        </div>

        <div class="space-section">
          <h3 class="space-section-title wb-subheading">Recently Used</h3>
          <div class="space-rows">
${recentRows}
          </div>
        </div>

        <p class="space-note">
          Everything here stays on this device. No account, no network, no sync.
        </p>
      </div>
    </div>`;
}

export default renderPersonalSpace;
